﻿ Reading from a Stream var fs = require("fs"); var data = '';
// Create a readable stream
var readerStream = fs.createReadStream('note.txt');
// Set the encoding to be utf8.
// readerStream.setEncoding('UTF8');
// Handle stream events --> data, end, and error readerStream.on('data', function(chunk) {
data += chunk;
});
readerStream.on('end',function() { console.log(data);
});
readerStream.on('error', function(err) { console.log(err.stack);
});

﻿ Writing to a stream const fileSystem = require("fs"); var data = "Sample text";
const writeStream = fileSystem.createWriteStream("output.txt"); writeStream.write(data, "UTF8");
writeStream.end() writeStream.on("finish", () => {
console.log("Finished writing");
});

writeStream.on("error", (error) => { console.log(error.stack);
});

﻿ Piping streams const fileSystem = require("fs");
const readStream = fileSystem.createReadStream(“note.txt"); 
const writeStream = fileSystem.createWriteStream("output.txt");
readStream.pipe(writeStream); 
console.log("Program finished"); Piping means connecting the output of one stream directly to the input of another stream.
It is mainly used to transfer data from a Readable Stream to a Writable Stream.

﻿ File system var fs = require("fs")
Synchronous vs Asynchronous

var fs = require("fs");
// Asynchronous read fs.readFile('input.txt’,function (err, data){ 
if (err){
return console.error(err);
}
console.log("Asynchronous read: " + data.toString());
});

// Synchronous read
var data = fs.readFileSync('input.txt’);
console.log("Synchronous read: " + data.toString()); 
console.log("Program Ended");

